              "code": "active"
            }
          ]
        },
        "note": [
          {
            "text": "Recent hospitalized COPD exacerbation. Currently clinically stable by history, with no clear current exacerbation, but markedly limited exercise tolerance and poor medication adherence. Assessed as high risk for further exacerbations."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
