      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-6",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-6",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Non-adherence to medications and follow-up"
