      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Sleep and nocturnal breathing symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Sleeping 'so-so'; worse when lying flat without CPAP. Nocturnal shortness of breath noted in assessment."
