        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Inhaler adherence"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient reports running out of the blue puffer a few weeks ago and using the grey one when remembered. Wife reports that he forgets half his puffers unless she reminds him."
      }
    },
    {
